package manage

import (
	"bytes"
	"context"
	"errors"
	"os/exec"
	"syscall"
	"time"
)

// ExecRunner runs only commands generated by this package, with a clean environment.
type ExecRunner struct{}

func (ExecRunner) Run(ctx context.Context, c Command) ([]byte, error) {
	ctx, cancel := context.WithTimeout(ctx, 15*time.Minute)
	defer cancel()
	cmd := exec.CommandContext(ctx, c.Path, c.Args...)
	cmd.Dir, cmd.Env = c.Dir, c.Env
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	// Keep cancellation active while Wait drains inherited output pipes, even
	// after the direct child exits and exec's context watcher stops.
	cmd.Cancel = nil
	cmd.WaitDelay = 2 * time.Second
	var out, stderr cappedBuffer
	cmd.Stdout, cmd.Stderr = &out, &stderr
	if err := cmd.Start(); err != nil {
		if ctx.Err() != nil {
			return nil, ctx.Err()
		}
		return nil, commandFailure(err, "")
	}
	finished := make(chan bool, 1)
	cleanup := make(chan error, 1)
	go func() {
		select {
		case <-ctx.Done():
		case needsCleanup := <-finished:
			if !needsCleanup && ctx.Err() == nil {
				cleanup <- nil
				return
			}
		}
		cleanup <- errors.Join(ctx.Err(), stopManagerGroup(cmd.Process.Pid))
	}()
	err := cmd.Wait()
	// Wait preserves ExitError over ErrWaitDelay, so any failed command must
	// clean up its group before its original status can be returned.
	finished <- err != nil
	cleanupErr := <-cleanup
	if cleanupErr != nil {
		return nil, cleanupErr
	}
	if out.overflow {
		return nil, errors.New("manager output exceeded limit")
	}
	if err != nil {
		return out.Bytes(), commandFailure(err, stderr.String())
	}
	return out.Bytes(), nil
}

func stopManagerGroup(pgid int) error {
	// Only the group created by Start belongs to this runner. Never retry a
	// signal after observing its disappearance, since the ID could be reused.
	if pgid <= 1 || pgid == syscall.Getpgrp() {
		return errors.New("manager process group cleanup refused")
	}
	if err := syscall.Kill(-pgid, syscall.SIGKILL); err != nil {
		if errors.Is(err, syscall.ESRCH) {
			return nil
		}
		return errors.New("manager process group termination failed")
	}
	until := time.Now().Add(2 * time.Second)
	for {
		err := syscall.Kill(-pgid, 0)
		if errors.Is(err, syscall.ESRCH) {
			return nil
		}
		// Darwin can briefly return EPERM while killed group members exit.
		// Only ESRCH confirms completion; keep probing within the same bound.
		if !time.Now().Before(until) {
			return errors.New("manager process group exit not confirmed")
		}
		time.Sleep(10 * time.Millisecond)
	}
}

type cappedBuffer struct {
	buffer   bytes.Buffer
	overflow bool
}

// Do not embed Buffer: its promoted ReadFrom would bypass the Write limit.
func (b *cappedBuffer) Bytes() []byte  { return b.buffer.Bytes() }
func (b *cappedBuffer) String() string { return b.buffer.String() }

func (b *cappedBuffer) Write(p []byte) (int, error) {
	n := len(p)
	left := (1 << 20) - b.buffer.Len()
	if len(p) > left {
		p = p[:left]
		b.overflow = true
	}
	_, _ = b.buffer.Write(p)
	return n, nil
}
